const updates = $json.result || [];
if (updates.length === 0) return [];
const maxId = Math.max(...updates.map(u => u.update_id));
try { await this.helpers.httpRequest({ method: 'GET', url: 'https://api.telegram.org/bot8808566374:AAHr_dTaSo--UPsEV0iYgeuO7hHWdRBkyjk/getUpdates?offset=' + (maxId+1) + '&timeout=0', json: true }); } catch (e) {}
const salida = [];
for (const body of updates) {
  const esCallback = !!body.callback_query;
  const chatId = esCallback ? body.callback_query.message.chat.id : (body.message && body.message.chat.id);
  const nombre = esCallback ? (body.callback_query.from.first_name || '') : ((body.message && body.message.from.first_name) || '');
  const texto = esCallback ? '' : ((body.message && body.message.text) || '');
  const callbackData = esCallback ? body.callback_query.data : '';
  const callbackQueryId = esCallback ? body.callback_query.id : '';
  if (esCallback) { try { await this.helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot8808566374:AAHr_dTaSo--UPsEV0iYgeuO7hHWdRBkyjk/answerCallbackQuery', body: { callback_query_id: callbackQueryId }, json: true }); } catch (e) {} }
  salida.push({ json: { esCallback, chatId: String(chatId), nombre, texto, callbackData } });
}
return salida;

const cb = $('Normalizar Update').item.json;
const sesion = $json;
const estado = sesion.ESTADO;
const enCurso = ['esperando_pv','esperando_necesita','esperando_conflicto','esperando_confirmacion','esperando_ajuste','esperando_eleccion'].includes(estado);
let accion = 'ignorar';
let opcionTexto = '';
if (!cb.esCallback) {
  if (cb.texto === '/estado') accion = 'estado';
  else if (cb.texto === '/telar' && enCurso) accion = 'retomar_o_nueva';
  else if (estado === 'inactivo' || estado === 'terminado' || !estado) accion = 'saludar';
  else if (estado === 'esperando_pv' && cb.texto && !cb.texto.startsWith('/')) { accion = 'respuesta_pv'; opcionTexto = cb.texto; }
  else if (estado === 'esperando_necesita' && cb.texto && !cb.texto.startsWith('/')) { accion = 'respuesta_necesita'; opcionTexto = cb.texto; }
  else if (estado === 'esperando_conflicto' && cb.texto && !cb.texto.startsWith('/')) { accion = 'respuesta_conflicto'; opcionTexto = cb.texto; }
  else if (estado === 'esperando_ajuste' && cb.texto && !cb.texto.startsWith('/')) { accion = 'respuesta_ajuste'; opcionTexto = cb.texto; }
  else if (estado === 'esperando_eleccion' && cb.texto && !cb.texto.startsWith('/')) { accion = 'capitulo_elegido'; opcionTexto = cb.texto; }
} else {
  if (cb.callbackData === 'telar_retomar') accion = 'retomar';
  else if (cb.callbackData === 'telar_nueva') accion = 'empezar_nueva';
  else if (cb.callbackData === 'telar_confirmar' && estado === 'esperando_confirmacion') accion = 'confirmar_urdimbre';
  else if (cb.callbackData === 'telar_ajustar' && estado === 'esperando_confirmacion') accion = 'pedir_ajuste';
  else if ((cb.callbackData === 'telar_A' || cb.callbackData === 'telar_B') && estado === 'esperando_eleccion') {
    accion = 'capitulo_elegido';
    opcionTexto = cb.callbackData === 'telar_A' ? sesion.OPCION_A : sesion.OPCION_B;
  }
}
return { json: { chatId: cb.chatId, nombre: cb.nombre, callbackData: cb.callbackData, sesion, accion, opcionTexto } };

const PASOS = ["Tu (zona de confort)","Necesidad","Ir","Buscar","Encontrar","Tomar (el sacrificio)","Volver","Cambiado (final)"];
const sesion = $json;
const chatId = sesion.CHAT_ID;
const numCap = parseInt(sesion.CAPITULO_ACTUAL);
const pasoActual = PASOS[numCap - 1];
const etiqueta = '[Capitulo ' + numCap + '/8 · ' + pasoActual + ']';
const marker = 'URDIMBRE:: ';
const hist = sesion.HISTORIAL || '';
const idx = hist.indexOf('\n\n');
const urdimbre = hist.startsWith(marker) ? hist.slice(marker.length, idx) : '';
const historiaSoFar = hist.startsWith(marker) ? hist.slice(idx + 2) : hist;
const prompt = 'Eres coautor de una historia interactiva de Engremiat. ' + urdimbre + ' Historia hasta ahora:\n' + (historiaSoFar || '(inicio de la historia)') + '\n\nPropon EXACTAMENTE 2 direcciones distintas y breves (1-2 frases cada una) para el capitulo ' + numCap + ' (' + pasoActual + '). Responde SOLO con JSON valido: {"opcion_a": "...", "opcion_b": "..."}';
return { json: { chatId, prompt, etiqueta } };

const prep = $('Construir prompt opciones').item.json;
const u = $json.usage || {};
const entrada = u.prompt_tokens || 0;
const salida = u.completion_tokens || 0;
const coste = Number(((entrada/1e6)*0.44 + (salida/1e6)*1.32).toFixed(6));
let texto = $json.choices[0].message.content.trim();
texto = texto.replace(/```json|```/g, '').trim();
let opciones;
try { opciones = JSON.parse(texto); } catch (e) { opciones = { opcion_a: 'Continuar con cautela', opcion_b: 'Actuar con decision' }; }
return { json: { chatId: prep.chatId, opcionA: opciones.opcion_a, opcionB: opciones.opcion_b, etiqueta: prep.etiqueta, entrada, salida, coste } };

