const TOPE_MENSUAL_USD = 5;
const desde = new Date(); desde.setDate(desde.getDate() - 30);
const url = 'http://100.107.171.88/api/database/rows/table/285/?user_field_names=true&filter__SERVICIO__single_select_equal=1076&filter__FECHA__date_after_or_equal=' + desde.toISOString().slice(0,10) + '&size=200';
