const r = $json;
const s = r.sesion;
const preguntas = {
  esperando_pv: '¿Quien la vive? ¿Desde que perspectiva la contamos?',
  esperando_necesita: '¿Que quiere a simple vista? ¿Que necesita de verdad?',
  esperando_conflicto: '¿Cual es el conflicto central?'
};
let texto;
if (s.ESTADO === 'esperando_eleccion') {
  texto = '[Capitulo ' + s.CAPITULO_ACTUAL + '] Retomamos donde lo dejaste.\n\nA) ' + s.OPCION_A + '\n\nB) ' + s.OPCION_B + '\n\n¿Que pasa ahora? (o escribe tu propia idea)';
} else {
  texto = 'Retomamos donde lo dejaste.\n\n' + (preguntas[s.ESTADO] || 'Continua respondiendo a la ultima pregunta.');
}
return { json: { chatId: r.chatId, texto, tieneBotones: s.ESTADO === 'esperando_eleccion', opcionA: s.OPCION_A, opcionB: s.OPCION_B } };

const r = $json;
const hist = r.sesion.HISTORIAL || '';
const marker = 'URDIMBRE:: ';
const urdimbreActual = hist.startsWith(marker) ? hist.slice(marker.length).split('\n\n')[0] : hist;
const systemPrompt = 'Ajusta esta Urdimbre segun el comentario del coordinador. Devuelve la Urdimbre completa ya ajustada, 3-4 frases, mismo estilo, sin explicar el cambio.';
const userPrompt = 'Urdimbre actual: ' + urdimbreActual + '\n\nAjuste pedido: ' + r.opcionTexto;
return { json: { chatId: r.chatId, systemPrompt, userPrompt } };
